#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTeleport: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Teleport

    public static func lift(_ handle: UInt64) throws -> Teleport {
        return Teleport(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Teleport) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Teleport {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Teleport, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


