@_documentation(visibility: private)
#endif
public func FfiConverterTypeTeleport_lift(_ handle: UInt64) throws -> Teleport {
    return try FfiConverterTypeTeleport.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeTeleport_lower(_ value: Teleport) -> UInt64 {
    return FfiConverterTypeTeleport.lower(value)
}






