public struct AppAboutInput: Equatable, Hashable {
    /**
     * `macos`, `linux` or `windows`.
     */
    public var platform: String
    /**
     * The full version (`0.2.0`, `0.2.0-staging.6`).
     */
    public var version: String
    /**
     * The build (the macOS app's `CFBundleVersion`, `0.2.0.123`; may be
     * empty).
     */
    public var build: String
    /**
     * This machine for an issue report (`macOS 26.0 (arm64)`).
     */
    public var os: String
    /**
     * The app updates itself (its updater is running).
     */
    public var updater: Bool
    /**
     * The updater checks on its own.
     */
    public var autoCheck: Bool
    /**
     * The updater downloads and installs on its own.
     */
    public var autoInstall: Bool
    /**
     * The chosen channel.
     */
    public var channel: AppUpdateChannel
    /**
     * The last check, as the shell formats a date; `None`: never.
     */
    public var lastCheck: String?
    /**
     * A check is running.
     */
    public var checking: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * `macos`, `linux` or `windows`.
         */platform: String,
        /**
         * The full version (`0.2.0`, `0.2.0-staging.6`).
         */version: String,
        /**
         * The build (the macOS app's `CFBundleVersion`, `0.2.0.123`; may be
         * empty).
         */build: String,
        /**
         * This machine for an issue report (`macOS 26.0 (arm64)`).
         */os: String,
        /**
         * The app updates itself (its updater is running).
         */updater: Bool,
        /**
         * The updater checks on its own.
         */autoCheck: Bool,
        /**
         * The updater downloads and installs on its own.
         */autoInstall: Bool,
        /**
         * The chosen channel.
         */channel: AppUpdateChannel,
        /**
         * The last check, as the shell formats a date; `None`: never.
         */lastCheck: String?,
        /**
         * A check is running.
         */checking: Bool) {
        self.platform = platform
        self.version = version
        self.build = build
        self.os = os
        self.updater = updater
        self.autoCheck = autoCheck
        self.autoInstall = autoInstall
        self.channel = channel
        self.lastCheck = lastCheck
        self.checking = checking
    }




}

