public struct AppApproveSheetState: Equatable, Hashable {
    /**
     * The device to approve.
     */
    public var deviceId: String
    /**
     * Its name.
     */
    public var name: String
    /**
     * Re-verification (no code) rather than a new device.
     */
    public var expired: Bool
    /**
     * The code as typed.
     */
    public var code: String
    /**
     * The approval runs (presence, then the relay).
     */
    public var busy: Bool
    /**
     * The last failure.
     */
    public var error: String?
    /**
     * The last code the relay saw expired: offers approving the waiting
     * device of this name by id instead (see [`code_expired_fallback`]).
     * Typing a new code clears it.
     */
    public var codeExpired: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The device to approve.
         */deviceId: String,
        /**
         * Its name.
         */name: String,
        /**
         * Re-verification (no code) rather than a new device.
         */expired: Bool,
        /**
         * The code as typed.
         */code: String,
        /**
         * The approval runs (presence, then the relay).
         */busy: Bool,
        /**
         * The last failure.
         */error: String?,
        /**
         * The last code the relay saw expired: offers approving the waiting
         * device of this name by id instead (see [`code_expired_fallback`]).
         * Typing a new code clears it.
         */codeExpired: Bool) {
        self.deviceId = deviceId
        self.name = name
        self.expired = expired
        self.code = code
        self.busy = busy
        self.error = error
        self.codeExpired = codeExpired
    }




}

