public struct AppOnboardingState: Equatable, Hashable {
    /**
     * Page.
     */
    public var step: AppOnboardingStep
    /**
     * Where `cua` was installed on first launch, when it was.
     */
    public var cliTarget: String?
    /**
     * Menu bar only (no notch). The same setting as Settings' "Spaces tab
     * in the notch".
     */
    public var menuBar: Bool
    /**
     * Signed-in identity.
     */
    public var identity: String?
    /**
     * Agents configured.
     */
    public var agents: [String]
    /**
     * The choice.
     */
    public var mode: AppOnboardingMode?
    /**
     * The installer's preselection (`--mode host`, MDM file).
     */
    public var installerMode: AppOnboardingMode?
    /**
     * This machine's system, once the drive was checked.
     */
    public var driveOs: AppSpaceOs?
    /**
     * `volume_mount_status`, when the daemon answered.
     */
    public var driveStatus: AppDriveMountInput?
    /**
     * The drive was checked (answered or not).
     */
    public var driveChecked: Bool
    /**
     * The Cua Volume checkbox (off by default).
     */
    public var driveMount: Bool
    /**
     * What the shell is running for the page.
     */
    public var driveRequest: AppDriveStepRequest?
    /**
     * Why mounting failed.
     */
    public var driveError: String?
    /**
     * `volume_storage`, when the daemon answered.
     */
    public var driveStorage: AppDriveStorageInput?
    /**
     * Where the files live, as picked.
     */
    public var storageChoice: AppStorageChoice
    /**
     * The home folder (paths show as `~/...`).
     */
    public var driveHome: String?
    /**
     * The user picked (the saved backend no longer decides).
     */
    public var storagePicked: Bool
    /**
     * The bucket form and its test or save
     * ([`crate::drive_settings`]'s state; its `request` is the shell's).
     */
    public var storage: AppStorageState
    /**
     * Done's "Launch at login" checkbox (ticked unless unticked). The
     * shell applies it when the first run finishes.
     */
    public var launchAtLogin: Bool
    /**
     * The usage-data switch on Welcome: the machine's telemetry setting
     * (Settings' "Share anonymous usage data", `cua telemetry off`), none
     * until the shell read it (then it shows on).
     */
    public var telemetry: AppTelemetryInput?
    /**
     * Settings, Experiments: the Cua Volume page (and its Done line) only
     * while Cua Volume is on. Off until the shell says otherwise.
     */
    public var experiments: AppExperiments

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Page.
         */step: AppOnboardingStep,
        /**
         * Where `cua` was installed on first launch, when it was.
         */cliTarget: String?,
        /**
         * Menu bar only (no notch). The same setting as Settings' "Spaces tab
         * in the notch".
         */menuBar: Bool,
        /**
         * Signed-in identity.
         */identity: String?,
        /**
         * Agents configured.
         */agents: [String],
        /**
         * The choice.
         */mode: AppOnboardingMode?,
        /**
         * The installer's preselection (`--mode host`, MDM file).
         */installerMode: AppOnboardingMode?,
        /**
         * This machine's system, once the drive was checked.
         */driveOs: AppSpaceOs?,
        /**
         * `volume_mount_status`, when the daemon answered.
         */driveStatus: AppDriveMountInput?,
        /**
         * The drive was checked (answered or not).
         */driveChecked: Bool,
        /**
         * The Cua Volume checkbox (off by default).
         */driveMount: Bool,
        /**
         * What the shell is running for the page.
         */driveRequest: AppDriveStepRequest?,
        /**
         * Why mounting failed.
         */driveError: String?,
        /**
         * `volume_storage`, when the daemon answered.
         */driveStorage: AppDriveStorageInput?,
        /**
         * Where the files live, as picked.
         */storageChoice: AppStorageChoice,
        /**
         * The home folder (paths show as `~/...`).
         */driveHome: String?,
        /**
         * The user picked (the saved backend no longer decides).
         */storagePicked: Bool,
        /**
         * The bucket form and its test or save
         * ([`crate::drive_settings`]'s state; its `request` is the shell's).
         */storage: AppStorageState,
        /**
         * Done's "Launch at login" checkbox (ticked unless unticked). The
         * shell applies it when the first run finishes.
         */launchAtLogin: Bool,
        /**
         * The usage-data switch on Welcome: the machine's telemetry setting
         * (Settings' "Share anonymous usage data", `cua telemetry off`), none
         * until the shell read it (then it shows on).
         */telemetry: AppTelemetryInput?,
        /**
         * Settings, Experiments: the Cua Volume page (and its Done line) only
         * while Cua Volume is on. Off until the shell says otherwise.
         */experiments: AppExperiments) {
        self.step = step
        self.cliTarget = cliTarget
        self.menuBar = menuBar
        self.identity = identity
        self.agents = agents
        self.mode = mode
        self.installerMode = installerMode
        self.driveOs = driveOs
        self.driveStatus = driveStatus
        self.driveChecked = driveChecked
        self.driveMount = driveMount
        self.driveRequest = driveRequest
        self.driveError = driveError
        self.driveStorage = driveStorage
        self.storageChoice = storageChoice
        self.driveHome = driveHome
        self.storagePicked = storagePicked
        self.storage = storage
        self.launchAtLogin = launchAtLogin
        self.telemetry = telemetry
        self.experiments = experiments
    }




}

