/**
 * One decoded video frame : packed top-down BGRA.
 */
public struct DecodedVideoFrame: Equatable, Hashable {
    /**
     * Per-target frame sequence.
     */
    public var sequence: UInt64
    /**
     * Width in pixels.
     */
    public var width: UInt32
    /**
     * Height in pixels.
     */
    public var height: UInt32
    /**
     * Bytes per row (`width * 4`).
     */
    public var stride: UInt32
    /**
     * Pixel format; always `bgra`.
     */
    public var format: String
    /**
     * Media-clock capture time (µs).
     */
    public var captureTimestampUs: UInt64
    /**
     * Decoder configuration generation of the source frame.
     */
    public var codecEpoch: UInt64
    /**
     * Coordinate generation.
     */
    public var geometryEpoch: UInt64
    /**
     * The source access unit was a keyframe.
     */
    public var keyframe: Bool
    /**
     * Bytes of the source (encoded) access unit.
     */
    public var encodedSize: UInt64
    /**
     * When the encoded frame reached the decoder (Unix µs, this host).
     */
    public var receivedAtUs: UInt64
    /**
     * Time spent decoding and converting it (µs).
     */
    public var decodeDurationUs: UInt64
    /**
     * Pixels.
     */
    public var data: Data

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Per-target frame sequence.
         */sequence: UInt64,
        /**
         * Width in pixels.
         */width: UInt32,
        /**
         * Height in pixels.
         */height: UInt32,
        /**
         * Bytes per row (`width * 4`).
         */stride: UInt32,
        /**
         * Pixel format; always `bgra`.
         */format: String,
        /**
         * Media-clock capture time (µs).
         */captureTimestampUs: UInt64,
        /**
         * Decoder configuration generation of the source frame.
         */codecEpoch: UInt64,
        /**
         * Coordinate generation.
         */geometryEpoch: UInt64,
        /**
         * The source access unit was a keyframe.
         */keyframe: Bool,
        /**
         * Bytes of the source (encoded) access unit.
         */encodedSize: UInt64,
        /**
         * When the encoded frame reached the decoder (Unix µs, this host).
         */receivedAtUs: UInt64,
        /**
         * Time spent decoding and converting it (µs).
         */decodeDurationUs: UInt64,
        /**
         * Pixels.
         */data: Data) {
        self.sequence = sequence
        self.width = width
        self.height = height
        self.stride = stride
        self.format = format
        self.captureTimestampUs = captureTimestampUs
        self.codecEpoch = codecEpoch
        self.geometryEpoch = geometryEpoch
        self.keyframe = keyframe
        self.encodedSize = encodedSize
        self.receivedAtUs = receivedAtUs
        self.decodeDurationUs = decodeDurationUs
        self.data = data
    }




}

