     * "Set up Keyvault" shows.
     */
    public var canSetup: Bool
    /**
     * "Unlock" shows.
     */
    public var canUnlock: Bool
    /**
     * The Disable switch shows (this app is first party, a vault exists).
     */
    public var killSwitchVisible: Bool
    /**
     * The switch can be flipped (unlocked).
     */
    public var killSwitchEnabled: Bool
    /**
     * The kill switch is on.
     */
