public struct KvStatus: Equatable, Hashable {
    /**
     * Version.
     */
    public var version: String
    /**
     * A vault exists.
     */
    public var initialized: Bool
    /**
     * Unlocked.
     */
    public var unlocked: Bool
    /**
     * The kill switch is on.
     */
    public var disabled: Bool
    /**
     * This app is first party.
     */
    public var callerFirstParty: Bool
    /**
     * How the broker sees this app.
     */
    public var callerDisplay: String
    /**
     * Items.
     */
    public var items: UInt32
    /**
     * Pending requests.
     */
    public var pending: UInt32
    /**
     * `auto` or `presence`.
     */
    public var unlockPolicy: String?
    /**
     * Delivered copies wipe themselves after their TTL (off by default;
     * none: not told, a broker before the setting or a third party).
     */
    public var autoWipe: Bool?
    /**
     * The daemon can create the OS key store protector (setup offers Touch
     * ID); false for a development daemon, which is passphrase-only.
     */
    public var osProtectorAvailable: Bool
    /**
     * A passphrase can always be chosen.
     */
    public var passphraseAvailable: Bool
    /**
     * Protector kinds that can unlock this vault now (`macos-keychain`,
     * `windows-credential`, `passphrase`, `recovery`).
     */
    public var unlockProtectors: [String]
    /**
     * The browse window is open until this time, Unix ms: item names are
     * visible until then.
     */
    public var browseUntilMs: UInt64?
    /**
     * "Never ask again" on the unlock prompt is on.
     */
    public var skipUnlockPrompt: Bool?
    /**
     * An earlier preview's vault was found and set aside.
     */
    public var resetNotice: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Version.
         */version: String,
        /**
         * A vault exists.
         */initialized: Bool,
        /**
         * Unlocked.
         */unlocked: Bool,
        /**
         * The kill switch is on.
         */disabled: Bool,
        /**
         * This app is first party.
         */callerFirstParty: Bool,
        /**
         * How the broker sees this app.
         */callerDisplay: String,
        /**
         * Items.
         */items: UInt32,
        /**
         * Pending requests.
         */pending: UInt32,
        /**
         * `auto` or `presence`.
         */unlockPolicy: String?,
        /**
         * Delivered copies wipe themselves after their TTL (off by default;
         * none: not told, a broker before the setting or a third party).
         */autoWipe: Bool?,
        /**
         * The daemon can create the OS key store protector (setup offers Touch
         * ID); false for a development daemon, which is passphrase-only.
         */osProtectorAvailable: Bool,
        /**
         * A passphrase can always be chosen.
         */passphraseAvailable: Bool,
        /**
         * Protector kinds that can unlock this vault now (`macos-keychain`,
         * `windows-credential`, `passphrase`, `recovery`).
         */unlockProtectors: [String],
        /**
         * The browse window is open until this time, Unix ms: item names are
         * visible until then.
         */browseUntilMs: UInt64?,
        /**
         * "Never ask again" on the unlock prompt is on.
         */skipUnlockPrompt: Bool?,
        /**
         * An earlier preview's vault was found and set aside.
         */resetNotice: String?) {
        self.version = version
        self.initialized = initialized
        self.unlocked = unlocked
        self.disabled = disabled
        self.callerFirstParty = callerFirstParty
        self.callerDisplay = callerDisplay
        self.items = items
        self.pending = pending
        self.unlockPolicy = unlockPolicy
        self.autoWipe = autoWipe
        self.osProtectorAvailable = osProtectorAvailable
        self.passphraseAvailable = passphraseAvailable
        self.unlockProtectors = unlockProtectors
        self.browseUntilMs = browseUntilMs
        self.skipUnlockPrompt = skipUnlockPrompt
        self.resetNotice = resetNotice
    }




}

