/**
 * Decoded audio : interleaved signed 16-bit PCM.
 */
public struct PcmAudio: Equatable, Hashable {
    /**
     * Track id from `NegotiatedAudio`.
     */
    public var trackId: UInt16
    /**
     * Samples per second per channel.
     */
    public var sampleRate: UInt32
    /**
     * Interleaved channels.
     */
    public var channels: UInt16
    /**
     * Media-clock time of the first sample (µs).
     */
    public var ptsUs: UInt64
    /**
     * Synthesized by packet-loss concealment for a lost packet.
     */
    public var concealed: Bool
    /**
     * RAU2 sequence of the packet this frame was decoded from (the packet
     * that revealed the loss, for concealed frames).
     */
    public var sequence: UInt32
    /**
     * RAU2 config epoch (the audio codec generation).
     */
    public var configEpoch: UInt8
    /**
     * Bytes of the encoded packet (0 for concealed frames).
     */
    public var encodedSize: UInt64
    /**
     * When the packet reached the decoder (Unix µs, this host).
     */
    public var receivedAtUs: UInt64
    /**
     * Time spent decoding the packet (µs).
     */
    public var decodeDurationUs: UInt64
    /**
     * Interleaved samples.
     */
    public var samples: [Int16]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Track id from `NegotiatedAudio`.
         */trackId: UInt16,
        /**
         * Samples per second per channel.
         */sampleRate: UInt32,
        /**
         * Interleaved channels.
         */channels: UInt16,
        /**
         * Media-clock time of the first sample (µs).
         */ptsUs: UInt64,
        /**
         * Synthesized by packet-loss concealment for a lost packet.
         */concealed: Bool,
        /**
         * RAU2 sequence of the packet this frame was decoded from (the packet
         * that revealed the loss, for concealed frames).
         */sequence: UInt32,
        /**
         * RAU2 config epoch (the audio codec generation).
         */configEpoch: UInt8,
        /**
         * Bytes of the encoded packet (0 for concealed frames).
         */encodedSize: UInt64,
        /**
         * When the packet reached the decoder (Unix µs, this host).
         */receivedAtUs: UInt64,
        /**
         * Time spent decoding the packet (µs).
         */decodeDurationUs: UInt64,
        /**
         * Interleaved samples.
         */samples: [Int16]) {
        self.trackId = trackId
        self.sampleRate = sampleRate
        self.channels = channels
        self.ptsUs = ptsUs
        self.concealed = concealed
        self.sequence = sequence
        self.configEpoch = configEpoch
        self.encodedSize = encodedSize
        self.receivedAtUs = receivedAtUs
        self.decodeDurationUs = decodeDurationUs
        self.samples = samples
    }




}

