// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum AppPickerEvent: Equatable, Hashable {

    /**
     * The catalog arrived.
     */
    case loaded(
        /**
         * Entries.
         */entries: [AppCatalogEntry]
    )
    /**
     * Something failed.
     */
    case failed(
        /**
         * Message.
         */message: String,
        /**
         * Strings found in the error's cause (code, message, detail).
         */causeTexts: [String],
        /**
         * The cause said Cua is installed.
         */causeInstalled: Bool
    )
    /**
     * Search.
     */
    case query(
        /**
         * Text.
         */query: String
    )
    /**
     * Highlight.
     */
    case select(
        /**
         * Id.
         */id: String
    )
    /**
     * Open the options for the highlighted (or given) app.
     */
    case choose(
        /**
         * Id.
         */id: String?
    )
    /**
     * Start on an app (a drop or a window drag).
     */
    case preselect(
        /**
         * Entry.
         */entry: AppCatalogEntry,
        /**
         * Files dropped with it.
         */files: [String]
    )
    /**
     * What moves.
     */
    case move(
        /**
         * Move.
         */moves: AppTeleportMove
    )
    /**
     * Add files.
     */
    case files(
        /**
         * Paths.
         */files: [String]
    )
    /**
     * Remove a file.
     */
    case removeFile(
        /**
         * Path.
         */path: String
    )
    /**
     * An opt-in checkbox ("Keep me signed in", "Saved passwords", ...).
     */
    case sensitive(
        /**
         * The group.
         */group: AppSensitiveGroup,
        /**
         * Checked.
         */value: Bool
    )
    /**
     * Plan.
     */
    case plan
    /**
     * The plan arrived.
     */
    case planned(
        /**
         * Plan.
         */plan: AppTeleportPlan
    )
    /**
     * The secrets checkbox.
     */
    case acknowledge(
        /**
         * Checked.
         */value: Bool
    )
    /**
     * The "Save to Keyvault" checkbox.
     */
    case saveToKeyvault(
        /**
         * Checked.
         */value: Bool
    )
    /**
     * The relay-plaintext warning's checkbox (S1).
     */
    case acknowledgeRelayPlaintext(
        /**
         * Checked.
         */value: Bool
    )
    /**
     * The browser's sites with counts arrived (and what was picked last time
     * for this app and Space, if anything).
     */
    case domainsLoaded(
        /**
         * The inventory.
         */inventory: KvInventory,
        /**
         * The sites sent last time.
         */remembered: [String]?
    )
    /**
     * The inventory could not be read (the review then sends what the plan
     * lists, as before).
     */
    case domainsFailed
    /**
     * Pick or drop one site.
     */
    case toggleDomain(
        /**
         * The site.
         */domain: String
    )
    /**
     * Pick or drop every site the search shows.
     */
    case selectShownDomains(
        /**
         * Pick (true) or drop.
         */value: Bool
    )
    /**
     * The sites list's search text.
     */
    case domainQuery(
        /**
         * Text.
         */text: String
    )
    /**
     * Turn a consent line on or off.
     */
    case toggleItem(
        /**
         * The consent item's key.
         */key: String
    )
    /**
     * Where to send from.
     */
    case sendFrom(
        /**
         * The source.
         */source: AppSendSource
    )
    /**
     * The app's saved Keyvault items (what the Keyvault holds for it).
     */
    case vaultItems(
        /**
         * How many can be sent.
         */count: UInt32,
        /**
         * When the newest was saved, Unix ms.
         */newestMs: Int64,
        /**
         * Now, Unix ms.
         */nowMs: Int64,
        /**
         * The ones chosen to send (ids).
         */selected: [String],
        /**
         * The app's saved passwords (ids): sent only when ticked.
         */passwordIds: [String]
    )
    /**
     * Tick or untick "Also send saved passwords".
     */
    case togglePasswords(
        /**
         * Ticked.
         */value: Bool
    )
    /**
     * The chosen saved items changed.
     */
    case vaultSelection(
        /**
         * The ids.
         */selected: [String]
    )
    /**
     * Confirm the review.
     */
    case confirm
    /**
     * A run event.
     */
    case progress(
        /**
         * Event.
         */event: AppTeleportRunEvent
    )
    /**
     * The run finished.
     */
    case finished(
        /**
         * Report.
         */report: AppTeleportRunReport
    )
    /**
     * Back.
     */
    case back





}

