public struct FfiConverterTypeAppPickerEvent: FfiConverterRustBuffer {
    typealias SwiftType = AppPickerEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AppPickerEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .loaded(entries: try FfiConverterSequenceTypeAppCatalogEntry.read(from: &buf)
        )

        case 2: return .failed(message: try FfiConverterString.read(from: &buf), causeTexts: try FfiConverterSequenceString.read(from: &buf), causeInstalled: try FfiConverterBool.read(from: &buf)
        )

        case 3: return .query(query: try FfiConverterString.read(from: &buf)
        )

        case 4: return .select(id: try FfiConverterString.read(from: &buf)
        )

        case 5: return .choose(id: try FfiConverterOptionString.read(from: &buf)
        )

        case 6: return .preselect(entry: try FfiConverterTypeAppCatalogEntry.read(from: &buf), files: try FfiConverterSequenceString.read(from: &buf)
        )

        case 7: return .move(moves: try FfiConverterTypeAppTeleportMove.read(from: &buf)
        )

        case 8: return .files(files: try FfiConverterSequenceString.read(from: &buf)
        )

        case 9: return .removeFile(path: try FfiConverterString.read(from: &buf)
        )

        case 10: return .sensitive(group: try FfiConverterTypeAppSensitiveGroup.read(from: &buf), value: try FfiConverterBool.read(from: &buf)
        )

        case 11: return .plan

        case 12: return .planned(plan: try FfiConverterTypeAppTeleportPlan.read(from: &buf)
        )

        case 13: return .acknowledge(value: try FfiConverterBool.read(from: &buf)
        )

        case 14: return .saveToKeyvault(value: try FfiConverterBool.read(from: &buf)
        )

        case 15: return .acknowledgeRelayPlaintext(value: try FfiConverterBool.read(from: &buf)
        )

        case 16: return .domainsLoaded(inventory: try FfiConverterTypeKvInventory.read(from: &buf), remembered: try FfiConverterOptionSequenceString.read(from: &buf)
        )

        case 17: return .domainsFailed

        case 18: return .toggleDomain(domain: try FfiConverterString.read(from: &buf)
        )

        case 19: return .selectShownDomains(value: try FfiConverterBool.read(from: &buf)
        )

        case 20: return .domainQuery(text: try FfiConverterString.read(from: &buf)
        )

        case 21: return .toggleItem(key: try FfiConverterString.read(from: &buf)
        )

        case 22: return .sendFrom(source: try FfiConverterTypeAppSendSource.read(from: &buf)
        )

        case 23: return .vaultItems(count: try FfiConverterUInt32.read(from: &buf), newestMs: try FfiConverterInt64.read(from: &buf), nowMs: try FfiConverterInt64.read(from: &buf), selected: try FfiConverterSequenceString.read(from: &buf), passwordIds: try FfiConverterSequenceString.read(from: &buf)
        )

        case 24: return .togglePasswords(value: try FfiConverterBool.read(from: &buf)
        )

        case 25: return .vaultSelection(selected: try FfiConverterSequenceString.read(from: &buf)
        )

        case 26: return .confirm

        case 27: return .progress(event: try FfiConverterTypeAppTeleportRunEvent.read(from: &buf)
        )

        case 28: return .finished(report: try FfiConverterTypeAppTeleportRunReport.read(from: &buf)
        )

        case 29: return .back

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AppPickerEvent, into buf: inout [UInt8]) {
        switch value {


        case let .loaded(entries):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypeAppCatalogEntry.write(entries, into: &buf)


        case let .failed(message,causeTexts,causeInstalled):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            FfiConverterSequenceString.write(causeTexts, into: &buf)
            FfiConverterBool.write(causeInstalled, into: &buf)


        case let .query(query):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(query, into: &buf)


        case let .select(id):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(id, into: &buf)


        case let .choose(id):
            writeInt(&buf, Int32(5))
            FfiConverterOptionString.write(id, into: &buf)


        case let .preselect(entry,files):
            writeInt(&buf, Int32(6))
            FfiConverterTypeAppCatalogEntry.write(entry, into: &buf)
            FfiConverterSequenceString.write(files, into: &buf)


        case let .move(moves):
            writeInt(&buf, Int32(7))
            FfiConverterTypeAppTeleportMove.write(moves, into: &buf)


        case let .files(files):
            writeInt(&buf, Int32(8))
            FfiConverterSequenceString.write(files, into: &buf)


        case let .removeFile(path):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(path, into: &buf)


        case let .sensitive(group,value):
            writeInt(&buf, Int32(10))
            FfiConverterTypeAppSensitiveGroup.write(group, into: &buf)
            FfiConverterBool.write(value, into: &buf)


        case .plan:
            writeInt(&buf, Int32(11))


        case let .planned(plan):
            writeInt(&buf, Int32(12))
            FfiConverterTypeAppTeleportPlan.write(plan, into: &buf)


        case let .acknowledge(value):
            writeInt(&buf, Int32(13))
            FfiConverterBool.write(value, into: &buf)


        case let .saveToKeyvault(value):
            writeInt(&buf, Int32(14))
            FfiConverterBool.write(value, into: &buf)


        case let .acknowledgeRelayPlaintext(value):
            writeInt(&buf, Int32(15))
            FfiConverterBool.write(value, into: &buf)


        case let .domainsLoaded(inventory,remembered):
            writeInt(&buf, Int32(16))
            FfiConverterTypeKvInventory.write(inventory, into: &buf)
            FfiConverterOptionSequenceString.write(remembered, into: &buf)


        case .domainsFailed:
            writeInt(&buf, Int32(17))


        case let .toggleDomain(domain):
            writeInt(&buf, Int32(18))
            FfiConverterString.write(domain, into: &buf)


        case let .selectShownDomains(value):
            writeInt(&buf, Int32(19))
            FfiConverterBool.write(value, into: &buf)


        case let .domainQuery(text):
            writeInt(&buf, Int32(20))
            FfiConverterString.write(text, into: &buf)


        case let .toggleItem(key):
            writeInt(&buf, Int32(21))
            FfiConverterString.write(key, into: &buf)


        case let .sendFrom(source):
            writeInt(&buf, Int32(22))
            FfiConverterTypeAppSendSource.write(source, into: &buf)


        case let .vaultItems(count,newestMs,nowMs,selected,passwordIds):
            writeInt(&buf, Int32(23))
            FfiConverterUInt32.write(count, into: &buf)
            FfiConverterInt64.write(newestMs, into: &buf)
            FfiConverterInt64.write(nowMs, into: &buf)
            FfiConverterSequenceString.write(selected, into: &buf)
            FfiConverterSequenceString.write(passwordIds, into: &buf)


        case let .togglePasswords(value):
            writeInt(&buf, Int32(24))
            FfiConverterBool.write(value, into: &buf)


        case let .vaultSelection(selected):
            writeInt(&buf, Int32(25))
            FfiConverterSequenceString.write(selected, into: &buf)


        case .confirm:
            writeInt(&buf, Int32(26))


        case let .progress(event):
