     */
    case chooseOs(
        /**
         * OS.
         */os: AppSpaceOs
    )
    /**
     * A preset picked from the suggestions (fills the field).
     */
    case chooseImage(
        /**
         * Image ref.
         */imageRef: String
    )
    /**
     * The image field changed (typing): filters the suggestions; a preset's
     * ref selects it, anything else is used as typed.
     */
    case setImageText(
        /**
         * Text.
         */text: String
    )
    /**
     * Show every preset (the field's menu button, or focus).
     */
    case openImageSuggestions
    /**
     * Up (-1) or Down (+1) in the suggestions; opens them when closed.
     */
    case moveImageSuggestion(
        /**
         * Rows to move.
         */delta: Int32
    )
    /**
     * Return: picks the highlighted preset, or keeps the typed text.
     */
    case pickImageSuggestion
    /**
     * Escape, or the field lost focus.
     */
    case dismissImageSuggestions
    /**
     * A "Run on" tile.
     */
    case setPlacement(
        /**
         * Location.
         */placement: AppLocation
    )
    /**
     * A connected cloud: creates there.
     */
    case chooseCloud(
        /**
         * The provider's word (`aws`).
         */cloud: String
    )
    /**
     * An entry of the "Run on" menu ([`PlacementOption::id`]): `local`,
     * `cloud`, `host:<machine>` or a connected cloud's word. A disabled
     * entry (offline, at its limit) is ignored.
     */
    case choosePlacement(
        /**
         * The entry's id.
         */on: String
    )
    /**
     * Show or hide Advanced.
     */
    case toggleAdvanced
    /**
     * A kind tile (switches to the family's image of that kind).
     */
    case chooseKind(
        /**
         * Kind.
         */kind: AppSpaceKind
    )
    /**
     * The runtime menu.
     */
    case setRuntime(
        /**
         * Runtime.
         */runtime: AppRuntime
    )
    /**
     * CPU slider.
     */
    case setCpus(
        /**
         * Cores.
         */cpus: UInt32
    )
    /**
     * Memory slider.
     */
    case setMemory(
        /**
         * GB.
         */memoryGb: UInt32
    )
    /**
     * Disk slider (VMs whose disk can grow).
     */
    case setDisk(
        /**
         * GB.
         */diskGb: UInt32
    )
    /**
     * The disk slider's Reset: back to the image's own disk.
     */
    case resetDisk
    /**
     * The GPU checkbox.
     */
    case setGpu(
        /**
         * Checked.
         */on: Bool
    )
    /**
     * Name field.
     */
    case setName(
        /**
         * Text.
         */name: String
    )
    /**
     * "Open when ready".
     */
    case setOpenWhenReady(
        /**
         * On.
         */on: Bool
    )
    /**
     * Continue.
     */
    case next
    /**
     * Back.
     */
    case back
    /**
     * "Connect by address..."
     */
    case showAddress
    /**
     * Back to create.
     */
    case hideAddress
