public struct FfiConverterTypeAppWizardAction: FfiConverterRustBuffer {
    typealias SwiftType = AppWizardAction

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AppWizardAction {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .syncDefault(location: try FfiConverterTypeAppLocation.read(from: &buf)
        )

        case 2: return .chooseOs(os: try FfiConverterTypeAppSpaceOs.read(from: &buf)
        )

        case 3: return .chooseImage(imageRef: try FfiConverterString.read(from: &buf)
        )

        case 4: return .setImageText(text: try FfiConverterString.read(from: &buf)
        )

        case 5: return .openImageSuggestions

        case 6: return .moveImageSuggestion(delta: try FfiConverterInt32.read(from: &buf)
        )

        case 7: return .pickImageSuggestion

        case 8: return .dismissImageSuggestions

        case 9: return .setPlacement(placement: try FfiConverterTypeAppLocation.read(from: &buf)
        )

        case 10: return .chooseCloud(cloud: try FfiConverterString.read(from: &buf)
        )

        case 11: return .choosePlacement(on: try FfiConverterString.read(from: &buf)
        )

        case 12: return .toggleAdvanced

        case 13: return .chooseKind(kind: try FfiConverterTypeAppSpaceKind.read(from: &buf)
        )

        case 14: return .setRuntime(runtime: try FfiConverterTypeAppRuntime.read(from: &buf)
        )

        case 15: return .setCpus(cpus: try FfiConverterUInt32.read(from: &buf)
        )

        case 16: return .setMemory(memoryGb: try FfiConverterUInt32.read(from: &buf)
        )

        case 17: return .setDisk(diskGb: try FfiConverterUInt32.read(from: &buf)
        )

        case 18: return .resetDisk

        case 19: return .setGpu(on: try FfiConverterBool.read(from: &buf)
        )

        case 20: return .setName(name: try FfiConverterString.read(from: &buf)
        )

        case 21: return .setOpenWhenReady(on: try FfiConverterBool.read(from: &buf)
        )

        case 22: return .next

        case 23: return .back

        case 24: return .showAddress

        case 25: return .hideAddress

        case 26: return .setAddress(url: try FfiConverterString.read(from: &buf)
        )

        case 27: return .setToken(token: try FfiConverterString.read(from: &buf)
        )

        case 28: return .setAddressName(name: try FfiConverterString.read(from: &buf)
        )

        case 29: return .submitAddress

        case 30: return .addressFailed(error: try FfiConverterString.read(from: &buf)
        )

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AppWizardAction, into buf: inout [UInt8]) {
        switch value {


        case let .syncDefault(location):
            writeInt(&buf, Int32(1))
            FfiConverterTypeAppLocation.write(location, into: &buf)


        case let .chooseOs(os):
            writeInt(&buf, Int32(2))
            FfiConverterTypeAppSpaceOs.write(os, into: &buf)


        case let .chooseImage(imageRef):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(imageRef, into: &buf)


        case let .setImageText(text):
            writeInt(&buf, Int32(4))
